    @Test("Lossless 16-bit decode is bit-exact")
    func lossless16BitDecode() throws {
        let img = try JLIDecoder().decode(from: Self.ll16)
        #expect(img.width == Self.w16 && img.height == Self.h16)
        #expect(img.pixelFormat == .uint16 && img.colorModel == .grayscale)
        #expect(img.data == Self.src16LE, "16-bit lossless decode not bit-exact")
    }

    @Test("Lossless 16-bit encode round-trips bit-exact")
    func lossless16BitRoundTrip() throws {
        let w = 18, h = 14
        var src = [UInt8](repeating: 0, count: w * h * 2)
        for i in 0..<(w * h) {
            let v = UInt16((i * 4099) & 0xFFFF)        // exercise the full 16-bit range
            src[i * 2] = UInt8(v & 0xFF); src[i * 2 + 1] = UInt8(v >> 8)
        }
        let img = try JLIImage(width: w, height: h, pixelFormat: .uint16, colorModel: .grayscale, data: src)
        for predictor in [1, 4, 7] {
            var cfg = JLIEncoderConfiguration.default
            cfg.lossless = true; cfg.losslessPredictor = predictor
            cfg.losslessPrecision = 16; cfg.chromaSubsampling = .yuv400
            let dec = try JLIDecoder().decode(from: try JLIEncoder().encode(img, configuration: cfg))
            #expect(dec.width == w && dec.height == h && dec.pixelFormat == .uint16)
            #expect(dec.data == src, "16-bit lossless predictor \(predictor) not bit-exact")
        }
    }

    @Test("Lossless color decode is bit-exact (RGB stored directly)")
    func losslessColorDecode() throws {
        let img = try JLIDecoder().decode(from: Self.colorLL)
        #expect(img.width == Self.colorW && img.height == Self.colorH)
        #expect(img.pixelFormat == .uint8 && img.colorModel == .rgb)
        #expect(img.data == Self.colorSrc, "color lossless decode not bit-exact")
    }

    @Test("Lossless color encode round-trips bit-exact")
    func losslessColorRoundTrip() throws {
        let w = 20, h = 16
        var rgb = [UInt8](repeating: 0, count: w * h * 3)
        for y in 0..<h {
            for x in 0..<w {
                let i = (y * w + x) * 3
                rgb[i] = UInt8((x * 11 + y * 3) & 0xFF)
                rgb[i + 1] = UInt8((y * 13 + x) & 0xFF)
                rgb[i + 2] = UInt8(((x + y) * 7) & 0xFF)
            }
        }
        let img = try JLIImage(width: w, height: h, pixelFormat: .uint8, colorModel: .rgb, data: rgb)
        for predictor in [1, 4, 7] {
            var cfg = JLIEncoderConfiguration.default
            cfg.lossless = true; cfg.losslessPredictor = predictor; cfg.chromaSubsampling = .yuv444
            let dec = try JLIDecoder().decode(from: try JLIEncoder().encode(img, configuration: cfg))
            #expect(dec.width == w && dec.height == h && dec.colorModel == .rgb)
            #expect(dec.data == rgb, "color lossless predictor \(predictor) not bit-exact")
        }
    }

    @Test("Lossless encode round-trips bit-exact for every predictor (8- and 12-bit)")
    func losslessEncodeRoundTrip() throws {
        let w = 24, h = 20
        var g8 = [UInt8](repeating: 0, count: w * h)
        for i in 0..<g8.count { g8[i] = UInt8((i * 13 + (i / w) * 7) & 0xFF) }
        var g12 = [UInt8](repeating: 0, count: w * h * 2)
        for i in 0..<(w * h) {
            let v = UInt16((i * 61) & 0x0FFF)
            g12[i * 2] = UInt8(v & 0xFF); g12[i * 2 + 1] = UInt8(v >> 8)
        }

        for predictor in 1...7 {
            var cfg = JLIEncoderConfiguration.default
            cfg.lossless = true; cfg.losslessPredictor = predictor; cfg.chromaSubsampling = .yuv400

            let img8 = try JLIImage(width: w, height: h, pixelFormat: .uint8, colorModel: .grayscale, data: g8)
            let dec8 = try JLIDecoder().decode(from: try JLIEncoder().encode(img8, configuration: cfg))
            #expect(dec8.width == w && dec8.height == h && dec8.pixelFormat == .uint8)
            #expect(dec8.data == g8, "8-bit lossless predictor \(predictor) not bit-exact")

            let img12 = try JLIImage(width: w, height: h, pixelFormat: .uint16, colorModel: .grayscale, data: g12)
            let dec12 = try JLIDecoder().decode(from: try JLIEncoder().encode(img12, configuration: cfg))
            #expect(dec12.pixelFormat == .uint16)
            #expect(dec12.data == g12, "12-bit lossless predictor \(predictor) not bit-exact")
        }
    }
}
